package main

import "net/http"

func ui(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("content-type", "text/html; charset=utf-8")
	w.Write([]byte(`<!doctype html><html><head><meta charset="utf-8"><meta name=viewport content="width=device-width,initial-scale=1"><title>PortHub</title><style>
:root{color-scheme:dark;--bg:#0b0f12;--panel:#11171c;--panel2:#151d23;--line:#27323a;--line2:#33414b;--text:#e6edf3;--muted:#8b9aa7;--green:#35c46a;--cyan:#42b8dd;--amber:#e2a93b;--red:#e15d55;--blue:#5d8cff}
*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font-family:Inter,ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,Segoe UI,sans-serif;letter-spacing:0}button,input,select{font:inherit}button{border:1px solid #2d8050;background:#1f7a47;color:white;border-radius:7px;padding:9px 12px;cursor:pointer;min-height:38px}button:hover{filter:brightness(1.08)}button.secondary{background:#1b242b;border-color:#394852;color:#d5dee7}button.danger{background:#742b2b;border-color:#934141}.iconbtn{width:38px;padding:0}input,select{background:#0d1216;color:var(--text);border:1px solid var(--line2);border-radius:7px;padding:9px 10px;min-width:0;min-height:38px}input:focus,select:focus{outline:2px solid rgba(66,184,221,.35);border-color:var(--cyan)}.app{display:grid;grid-template-columns:252px 1fr;min-height:100vh}.side{background:#0e1418;border-right:1px solid var(--line);padding:18px 14px;position:sticky;top:0;height:100vh}.brand{display:flex;gap:10px;align-items:center;padding:4px 6px 18px}.mark{width:34px;height:34px;border:1px solid #2d7f60;border-radius:8px;display:grid;place-items:center;color:#68e09b;background:#102019;font-weight:800}.brand h1{font-size:20px;margin:0}.brand p{margin:2px 0 0;color:var(--muted);font-size:12px}.nav{display:grid;gap:6px}.nav a{color:#aab8c4;text-decoration:none;padding:10px 12px;border-radius:7px;border:1px solid transparent}.nav a.active,.nav a:hover{background:#141c22;border-color:#2c3942;color:var(--text)}.content{min-width:0}.topbar{height:62px;border-bottom:1px solid var(--line);display:flex;align-items:center;justify-content:space-between;padding:0 20px;background:#0d1317;position:sticky;top:0;z-index:3}.topbar strong{font-size:15px}.badge{display:inline-flex;align-items:center;gap:7px;padding:5px 9px;border-radius:999px;border:1px solid var(--line2);color:#b9c6d0;background:#111820;font-size:12px}.dot{width:8px;height:8px;border-radius:50%;background:var(--muted)}.dot.ok{background:var(--green)}.dot.warn{background:var(--amber)}.wrap{padding:18px;max-width:1520px}.login{margin-bottom:16px}.login.hide{display:none}.section{border:1px solid var(--line);background:var(--panel);border-radius:8px;padding:14px;margin-bottom:14px}.section h2{font-size:16px;margin:0 0 12px}.section-title{display:flex;align-items:center;justify-content:space-between;gap:10px;margin-bottom:12px}.section-title h2{margin:0}.muted{color:var(--muted)}.ok{color:var(--green)}.bad{color:var(--red)}.grid{display:grid;gap:12px}.metrics{grid-template-columns:repeat(6,minmax(140px,1fr))}.metric{border:1px solid var(--line);background:var(--panel2);border-radius:8px;padding:13px;min-height:86px}.metric span{display:block;color:var(--muted);font-size:12px}.metric b{display:block;font-size:24px;margin-top:8px}.metric small{color:#9fb0bd}.topology{display:grid;grid-template-columns:repeat(5,1fr);gap:12px;align-items:stretch}.node{border:1px solid var(--line);background:#10161b;border-radius:8px;padding:12px;min-height:96px;position:relative}.node:after{content:"";position:absolute;right:-13px;top:47px;width:13px;border-top:1px solid #46606f}.node:last-child:after{display:none}.node span{display:block;color:var(--muted);font-size:12px}.node b{display:block;margin-top:5px}.node .status{margin-top:13px}.forms{display:grid;grid-template-columns:repeat(12,1fr);gap:9px;align-items:end}.forms label{display:grid;gap:5px;color:var(--muted);font-size:12px}.span2{grid-column:span 2}.span3{grid-column:span 3}.span4{grid-column:span 4}.span6{grid-column:span 6}.actions{display:flex;gap:8px;align-items:center;flex-wrap:wrap}.tablewrap{overflow:auto;border:1px solid var(--line);border-radius:8px}table{width:100%;border-collapse:collapse;min-width:820px;background:#10161b}th,td{border-bottom:1px solid var(--line);padding:10px;text-align:left;vertical-align:middle}th{color:#9fb0bd;font-size:12px;background:#141b21;position:sticky;top:0}td{font-size:14px}.pill{display:inline-flex;align-items:center;gap:6px;border:1px solid var(--line2);border-radius:999px;padding:3px 8px;font-size:12px}.pill.green{color:#6be28f;border-color:#2d7c4a;background:#102018}.pill.gray{color:#a4b1bd}.pill.cyan{color:#72d8ef;border-color:#2d6f80;background:#102027}pre{white-space:pre-wrap;background:#0c1115;border:1px solid var(--line);border-radius:8px;padding:12px;max-height:360px;overflow:auto;color:#b9c6d0}.split{display:grid;grid-template-columns:1.2fr .8fr;gap:14px}.toast{position:fixed;right:18px;bottom:18px;background:#122018;border:1px solid #2b7e4c;border-radius:8px;padding:12px 14px;display:none;max-width:420px;z-index:5}.toast.show{display:block}.toolbar{display:flex;align-items:center;justify-content:space-between;gap:10px;margin-bottom:10px}@media(max-width:1100px){.metrics{grid-template-columns:repeat(3,1fr)}.topology{grid-template-columns:1fr}.node:after{display:none}.split{grid-template-columns:1fr}.forms{grid-template-columns:repeat(6,1fr)}.span2,.span3,.span4,.span6{grid-column:span 6}}@media(max-width:760px){.app{grid-template-columns:1fr}.side{position:static;height:auto;border-right:0;border-bottom:1px solid var(--line)}.nav{grid-template-columns:repeat(2,1fr)}.topbar{position:static;padding:0 12px}.wrap{padding:12px}.metrics{grid-template-columns:repeat(2,1fr)}.forms{grid-template-columns:1fr}.span2,.span3,.span4,.span6{grid-column:span 1}}
.traffic-grid{display:grid;grid-template-rows:auto auto auto;gap:12px}.traffic-card{border:1px solid var(--line);background:#0f151a;border-radius:8px;padding:12px;min-height:116px}.traffic-card h3{margin:0 0 10px;font-size:13px;color:#cdd7df}.rank-list,.sample-list{display:grid;gap:9px}.rank-row{display:grid;gap:6px}.rank-meta,.sample-row{display:flex;align-items:center;justify-content:space-between;gap:10px;font-size:12px}.rank-meta strong{font-size:13px;color:#e6edf3}.bar-track{height:8px;background:#162129;border:1px solid #263742;border-radius:999px;overflow:hidden}.bar-fill{height:100%;background:linear-gradient(90deg,#34c46b,#42b8dd);border-radius:999px}.spark{width:100%;height:128px;background:#0c1115;border:1px solid var(--line);border-radius:8px}.spark text{fill:#8b9aa7;font-size:10px}.sample-row{border-top:1px solid var(--line);padding-top:8px;color:#aebbc6}.sample-row:first-child{border-top:0;padding-top:0}@media(max-width:760px){.traffic-card{min-height:auto}}
</style></head><body><div class=app><aside class=side><div class=brand><div class=mark>PH</div><div><h1>PortHub</h1><p>公网入口管理平台</p></div></div><nav class=nav><a class=active href="#overview">总览</a><a href="#publish">发布入口</a><a href="#mappings">TCP/UDP 映射</a><a href="#proxy">HTTP/HTTPS 代理</a><a href="#security">ACL 安全</a><a href="#deploy">配置快照</a><a href="#audit">审计日志</a></nav></aside><main class=content><header class=topbar><div><strong>PortHub 控制台</strong><span class=badge style="margin-left:10px"><span id=stateDot class="dot warn"></span><span id=state>未登录</span></span></div><div class=actions><span class=badge>Edge 203.0.113.10</span><button class=secondary onclick=refreshSafe()>刷新</button></div></header><div class=wrap>
<section id=login class="section login"><div class=section-title><h2>管理员登录</h2><span class=muted>Session + TOTP + CSRF</span></div><div class=forms><label class=span3>用户名<input id=user value=admin autocomplete=username></label><label class=span3>密码<input id=pass type=password autocomplete=current-password></label><label class=span2>TOTP<input id=totp inputmode=numeric placeholder=000000></label><div class=span2><button onclick=login()>登录</button></div></div></section>
<section id=overview class=section><div class=section-title><h2>运行总览</h2><span id=deployState class=muted></span></div><div class="grid metrics"><div class=metric><span>Core</span><b id=core>--</b><small>控制面</small></div><div class=metric><span>Edge</span><b id=edge>--</b><small>公网数据面</small></div><div class=metric><span>WireGuard</span><b>wg-porthub</b><small>10.255.0.0/24</small></div><div class=metric><span>映射</span><b id=count>0</b><small>TCP / UDP</small></div><div class=metric><span>Edge 包</span><b id=pkts>0</b><small>nft counter</small></div><div class=metric><span>Edge 字节</span><b id=bytes>0</b><small id=bytesHuman>0 B</small></div></div></section>
<section class=section><div class=section-title><h2>网络拓扑</h2><span class=muted>Internet 到内网资源的实际路径</span></div><div class=topology><div class=node><span>公网客户端</span><b>Internet</b><div class=status><span class="pill cyan">入口流量</span></div></div><div class=node><span>公网 VPS</span><b>PortHub Edge</b><div class=status><span class="pill green">在线</span></div></div><div class=node><span>加密隧道</span><b>WireGuard</b><div class=status><span class="pill green">wg-porthub</span></div></div><div class=node><span>局域网控制面</span><b>PortHub Core</b><div class=status><span class="pill green">在线</span></div></div><div class=node><span>内网资源</span><b>NAS / Docker / PVE</b><div class=status><span class="pill gray">受控发布</span></div></div></div></section>
<section id=publish class=section><div class=section-title><h2>快速发布</h2><span class=muted>模板会先生成映射，确认后再下发 Edge</span></div><div class=forms><label class=span3>模板<select id=tpl></select></label><label class=span3>发布名称<input id=tplname placeholder=例如 Minecraft 给朋友></label><label class=span3>目标 IP<input id=tpltarget value=10.255.0.2></label><label class=span2>启用状态<select id=tplenabled><option value=false>先保存为禁用</option><option value=true>直接启用</option></select></label><div class=span1><button class=iconbtn onclick=applyTpl()>+</button></div></div><p id=tplwarn class=muted></p></section>
<section id=mappings class=section><div class=section-title><h2>TCP / UDP 映射</h2><div class=actions><button class=secondary onclick=preview()>预览 nft</button><button onclick=deploy()>下发</button></div></div><div class=forms><label class=span2>名称<input id=mname placeholder=饥荒 Master></label><label>协议<select id=proto><option value=tcp>TCP</option><option value=udp>UDP</option><option value=tcpudp>TCP+UDP</option></select></label><label>公网起始<input id=ps inputmode=numeric></label><label>公网结束<input id=pe inputmode=numeric></label><label class=span2>目标 IP<input id=tip value=10.255.0.2></label><label>目标起始<input id=ts inputmode=numeric></label><label>目标结束<input id=te inputmode=numeric></label><label>状态<select id=enabled><option value=true>启用</option><option value=false>禁用</option></select></label><div><button onclick=createMapping()>新增</button></div></div><p class=muted>同一 Edge、同一公网 IP、同一协议端口会在保存前检测冲突。</p><div class=tablewrap><table><thead><tr><th>ID</th><th>名称</th><th>协议</th><th>公网端口</th><th>目标</th><th>状态</th><th>操作</th></tr></thead><tbody id=rows></tbody></table></div></section>
<section id=proxy class=section><div class=section-title><h2>HTTP / HTTPS 代理</h2><span class=muted>Edge: 18090/tcp 和 18443/tcp</span></div><div class=forms><label class=span2>名称<input id=hpname placeholder=NAS Web></label><label class=span3>Host<input id=hphost placeholder=nas.example.com></label><label>Path<input id=hppath value="/"></label><label class=span3>后端<input id=hptarget placeholder="http://10.255.0.2:9731"></label><label>状态<select id=hpenabled><option value=true>启用</option><option value=false>禁用</option></select></label><div><button onclick=createHTTPProxy()>新增</button></div></div><pre id=hprows></pre></section>
<section id=security class=section><div class=section-title><h2>ACL 安全</h2><span class=muted>当前支持全局黑名单 CIDR</span></div><div class=forms><label class=span3>名称<input id=aclname placeholder=Block test net></label><label class=span3>CIDR / 单 IP<input id=aclcidr placeholder=203.0.113.0/24></label><label class=span2>状态<select id=aclenabled><option value=true>启用</option><option value=false>禁用</option></select></label><div><button onclick=createACL()>新增黑名单</button></div></div><pre id=aclrows></pre></section>
<section id=deploy class=section><div class=section-title><h2>配置快照</h2><div class=actions><button class=secondary onclick=edgeMetrics()>刷新 Edge 计数</button><button class=secondary onclick=trafficSnapshot()>采集流量样本</button><button class=secondary onclick=preview()>预览 nft</button><button onclick=deploy()>签名并下发</button></div></div><div class=split><pre id=previewBox></pre><div class=traffic-grid><div class=traffic-card><h3>端口流量排行</h3><div id=rankBox class=rank-list><div class=muted>暂无排行</div></div></div><div class=traffic-card><h3 id=trendTitle>端口趋势</h3><svg id=trendSvg class=spark viewBox="0 0 320 128" preserveAspectRatio="none"></svg></div><div class=traffic-card><h3>最近采样</h3><div id=sampleBox class=sample-list><div class=muted>暂无样本</div></div></div></div></div></section>
<section id=audit class=section><div class=section-title><h2>最近审计</h2><span class=muted>最近 20 条</span></div><pre id=auditBox></pre></section>
</div></main></div><div id=toast class=toast></div><script>
let csrf='',currentMappings=[],templates=[];
async function api(path,opt={}){opt.headers=Object.assign({'content-type':'application/json'},opt.headers||{});if(opt.method&&opt.method!=='GET')opt.headers['X-CSRF-Token']=csrf;const r=await fetch(path,opt);const t=await r.text();if(!r.ok)throw new Error(t||r.status);return t?JSON.parse(t):{}}
async function login(){try{const body={Username:user.value,Password:pass.value,TOTP:totp.value};const r=await api('/api/login',{method:'POST',body:JSON.stringify(body)});csrf=r.csrf;state.textContent='已登录';stateDot.className='dot ok';document.getElementById('login').classList.add('hide');notice('登录成功');await refresh()}catch(e){notice('登录失败: '+e.message,true)}}
async function refreshSafe(){try{await refresh();notice('已刷新')}catch(e){notice('刷新失败: '+e.message,true)}}
async function refresh(){const s=await api('/api/status');core.textContent=s.core;edge.textContent=s.edge;templates=await api('/api/templates/builtin');tpl.innerHTML=templates.map(t=>'<option value="'+t.id+'">'+esc(t.name)+(t.high_risk?' - 高风险':'')+'</option>').join('');showTplWarn();const ms=await api('/api/mappings');currentMappings=ms||[];count.textContent=currentMappings.length;rows.innerHTML=currentMappings.map(rowMapping).join('');aclrows.textContent=JSON.stringify(await api('/api/acl-rules')||[],null,2);hprows.textContent=JSON.stringify(await api('/api/http-proxies')||[],null,2);await edgeMetrics();await trafficRecent();const a=await api('/api/audit');auditBox.textContent=JSON.stringify((a||[]).slice(0,20),null,2)}
function rowMapping(m){return '<tr><td>'+m.ID+'</td><td>'+esc(m.Name)+'</td><td><span class=\"pill cyan\">'+m.Protocol+'</span></td><td>'+m.PublicStart+'-'+m.PublicEnd+'</td><td>'+esc(m.TargetIP)+':'+m.TargetStart+'-'+m.TargetEnd+'</td><td>'+(m.Enabled?'<span class=\"pill green\">启用</span>':'<span class=\"pill gray\">禁用</span>')+'</td><td><button class=secondary onclick=toggle('+m.ID+')>'+(m.Enabled?'禁用':'启用')+'</button> <button class=danger onclick=del('+m.ID+')>删除</button></td></tr>'}
async function createMapping(){try{const body={Name:mname.value,Protocol:proto.value,PublicStart:+ps.value,PublicEnd:+(pe.value||ps.value),TargetIP:tip.value,TargetStart:+ts.value,TargetEnd:+(te.value||ts.value),Enabled:enabled.value==='true'};await api('/api/mappings',{method:'POST',body:JSON.stringify(body)});notice('映射已创建');await refresh()}catch(e){notice(e.message,true)}}
async function applyTpl(){try{const t=templates.find(x=>x.id===tpl.value);const body={template_id:tpl.value,name:tplname.value||t.name,target_ip:tpltarget.value,enabled:tplenabled.value==='true',allow_high_risk:false};const r=await api('/api/templates/apply',{method:'POST',body:JSON.stringify(body)});notice(r.high_risk?'高风险模板已保存为禁用':'模板已生成 '+r.created+' 条映射');await refresh()}catch(e){notice(e.message,true)}}
async function createACL(){try{await api('/api/acl-rules',{method:'POST',body:JSON.stringify({Name:aclname.value,Action:'deny',CIDR:aclcidr.value,Enabled:aclenabled.value==='true'})});notice('ACL 已创建');await refresh()}catch(e){notice(e.message,true)}}
async function createHTTPProxy(){try{await api('/api/http-proxies',{method:'POST',body:JSON.stringify({name:hpname.value,host:hphost.value,path:hppath.value||'/',target:hptarget.value,enabled:hpenabled.value==='true'})});notice('HTTP 代理已创建');await refresh()}catch(e){notice(e.message,true)}}
function showTplWarn(){const t=templates.find(x=>x.id===tpl.value);tplwarn.textContent=t?(t.warning||t.description):''}
document.addEventListener('change',e=>{if(e.target&&e.target.id==='tpl')showTplWarn()})
async function toggle(id){try{const m=currentMappings.find(x=>String(x.ID)===String(id));if(!m)return;m.Enabled=!m.Enabled;await api('/api/mappings',{method:'PUT',body:JSON.stringify(m)});notice('映射已更新');await refresh()}catch(e){notice(e.message,true)}}
async function del(id){try{await api('/api/mappings?id='+id,{method:'DELETE'});notice('映射已删除');await refresh()}catch(e){notice(e.message,true)}}
async function preview(){try{const r=await api('/api/nft/preview');previewBox.textContent=r.nft;notice('预览已生成')}catch(e){notice(e.message,true)}}
async function deploy(){try{deployState.textContent='下发中';const r=await api('/api/deploy',{method:'POST',body:'{}'});deployState.textContent='已下发版本 '+r.version;notice('Edge 已应用新快照');await refresh()}catch(e){deployState.textContent='下发失败';notice(e.message,true)}}
async function edgeMetrics(){try{const m=await api('/api/edge/metrics');pkts.textContent=m.packets||0;bytes.textContent=m.bytes||0;bytesHuman.textContent=fmtBytes(m.bytes||0)}catch(e){pkts.textContent='--';bytes.textContent='--';bytesHuman.textContent='不可用'}}
async function trafficSnapshot(){try{const s=await api('/api/traffic/snapshot',{method:'POST',body:'{}'});notice('流量样本已采集 '+fmtBytes(s.bytes||0));await trafficRecent()}catch(e){notice(e.message,true)}}
async function trafficRecent(){try{const rows=await api('/api/traffic/recent?limit=8');const rank=await api('/api/traffic/rank?limit=8');renderRank(rank||[]);renderSamples(rows||[]);const top=(rank||[])[0];if(top&&top.protocol&&top.port){const trend=await api('/api/traffic/trend?protocol='+encodeURIComponent(top.protocol)+'&port='+encodeURIComponent(top.port)+'&limit=24');renderTrend(trend||[],top)}else{renderTrend([],null)}}catch(e){rankBox.innerHTML='<div class=muted>暂无流量排行</div>';sampleBox.innerHTML='<div class=muted>暂无采样记录</div>';renderTrend([],null)}}
function renderRank(rank){if(!rank.length){rankBox.innerHTML='<div class=muted>暂无排行</div>';return}const max=Math.max.apply(null,rank.map(x=>Number(x.bytes||0)).concat([1]));rankBox.innerHTML=rank.map(x=>{const width=Math.max(4,Math.round(Number(x.bytes||0)*100/max));const label=esc(String(x.protocol||'').toUpperCase()+' '+x.port+' -> '+(x.target||''));return '<div class=rank-row><div class=rank-meta><strong>'+label+'</strong><span>'+fmtBytes(Number(x.bytes||0))+' / '+(x.packets||0)+' pkt</span></div><div class=bar-track><div class=bar-fill style="width:'+width+'%"></div></div></div>'}).join('')}
function renderSamples(rows){if(!rows.length){sampleBox.innerHTML='<div class=muted>暂无样本</div>';return}sampleBox.innerHTML=rows.map(x=>'<div class=sample-row><span>'+shortTime(x.ts)+' 版本 '+esc(x.edge_version||'--')+'</span><strong>'+fmtBytes(Number(x.bytes||0))+'</strong></div>').join('')}
function renderTrend(rows,top){const title=top?String(top.protocol||'').toUpperCase()+' '+top.port+' 趋势':'端口趋势';trendTitle.textContent=title;const data=(rows||[]).slice().reverse();if(data.length<2){trendSvg.innerHTML='<text x="18" y="68">暂无足够趋势样本</text>';return}const values=data.map(x=>Number(x.bytes||0));const max=Math.max.apply(null,values.concat([1]));const min=Math.min.apply(null,values);const span=Math.max(1,max-min);const points=data.map((x,i)=>{const px=14+i*(292/Math.max(1,data.length-1));const py=108-((Number(x.bytes||0)-min)*82/span);return px.toFixed(1)+','+py.toFixed(1)}).join(' ');trendSvg.innerHTML='<path d="M14 108H306" stroke="#263742" stroke-width="1"/><polyline fill="none" stroke="#42b8dd" stroke-width="3" stroke-linecap="round" stroke-linejoin="round" points="'+points+'"/><text x="16" y="20">'+fmtBytes(max)+'</text><text x="16" y="122">'+fmtBytes(min)+'</text>'}
function shortTime(s){const d=new Date(s);return isNaN(d.getTime())?(s||'--'):d.toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit',second:'2-digit'})}
function fmtBytes(n){if(n<1024)return n+' B';if(n<1048576)return(n/1024).toFixed(1)+' KiB';return(n/1048576).toFixed(1)+' MiB'}
function esc(s){return(s||'').replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]))}
function notice(msg,bad){toast.textContent=msg;toast.style.borderColor=bad?'#934141':'#2b7e4c';toast.style.background=bad?'#241313':'#122018';toast.classList.add('show');setTimeout(()=>toast.classList.remove('show'),3200)}
</script></body></html>`))
}
